import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, InputLabel } from '@mui/material';
import Iconify from '../../components/iconify';
import { useMyContext } from '../provider';
import useResponsive from '../../hooks/useResponsive';
import InputField from '../../components/input/inputField';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';

const AdvCategoryForm = () => {
    const navigate = useNavigate();
    const { i18 } = useMyContext();
    const location = useLocation();
    const isMobile = useResponsive('down', 'sm');
    const [categoryName, setCategoryName] = useState('');
    const [iconImage, setIconImage] = useState(null);
    const [iconPreview, setIconPreview] = useState('');
    const [categoryimage, setCategoryImage] = useState(null);
    const [categoryPreview, setCategoryPreview] = useState('');
    const [error, setError] = useState('');

    const { cateId, property, icon, image } = location?.state || { cateId: '', property: '', img: '' };
    
    useEffect(() => {
        if (property) setCategoryName(property);
        if (icon) {
            setIconImage(icon);
            setIconPreview(IMAGE_URL + icon);
            // setCategoryPreview
        }
        if(image) {
            setCategoryImage(image);
            setCategoryPreview(IMAGE_URL + image);
        }
    }, [property, icon, image])

    const backToRoute = () => {
        navigate('/dashboard/category&subcategory');
    };

    const handlePropertyChange = (event) => {
        const { value } = event.target;
        if (/^[A-Za-z\s]*$/.test(value)) {
            setCategoryName(value);
            if (value.length < 2) {
                setError('Property is too short');
            } else {
                setError('');
            }
        }
    };

    const handleIconUpload = (event) => {
        const file = event.target.files[0];
        if (file && file.type === 'image/png') {
            setIconImage(file);
            const reader = new FileReader();
            reader.onloadend = () => {
                setIconPreview(reader.result);
            };
            reader.readAsDataURL(file);
        } else {
            setError('Please upload a valid PNG image');
            setIconImage(null);
            setIconPreview('');
            event.target.value = '';
        }
    };

    const handleImageUpload = (event) => {
        const file = event.target.files[0];
        if (file && file.type.startsWith('image/')) {
            setCategoryImage(file);
            const reader = new FileReader();
            reader.onloadend = () => {
                setCategoryPreview(reader.result);
            };
            reader.readAsDataURL(file);
        } else {
            setError('Please upload a valid image');
            setCategoryImage(null);
            setCategoryPreview('');
            event.target.value = '';
        }
    };

    const addorUpdateCategory = async () => {
        const formData = new FormData();
        formData.append('category', categoryName);
        if (iconImage) {
            formData.append('icon', iconImage);
        }
        if(categoryimage) {
            formData.append('image', iconImage);
        }

        try {
            const url = cateId ? `module/ads/admin/category/${cateId}` : 'module/ads/admin/category';
            const method = cateId ? 'put' : 'post';

            const response = await axios[method](url, formData);

            if (response?.status === 200 || response?.status === 201) {
                GenerateToastConfig(response?.data?.message, 'success');
                navigate('/dashboard/category&subcategory')
            }
        } catch (error) {
            GenerateToastConfig(error.message, 'error');
        }
    };

    return (
        <>
            <Helmet>
                <title>{cateId ? 'Edit Category' : 'Add Category'}</title>
            </Helmet>
            <Card>
                <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <Box
                                sx={{
                                    width: '37px',
                                    height: '37px',
                                    background: '#FF5A60',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    borderRadius: '50%',
                                    cursor: 'pointer',
                                }}
                                onClick={backToRoute}
                            >
                                <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
                            </Box>
                            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                {cateId ? i18?.ACCOUNTSTITLE?.EDIT_CATEGORY || "Edit Category" : i18?.ACCOUNTSTITLE?.ADD_CATEGORY || "Add Category"}
                            </Typography>
                        </Box>
                    </Grid>
                </Grid>

                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputField
                            value={categoryName}
                            name="categoryName"
                            label={i18?.ACCOUNTSTITLE?.CATEGORYNAME || "Category Name"}
                            sx={{
                                margin: '10px 0px',
                                width: '100%',
                                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px',
                                },
                            }}
                            onChange={handlePropertyChange}
                            type="text"
                            required
                        />
                        {error && <Typography color="error">{error}</Typography>}
                    </Grid>
                    <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputLabel sx={{ color: "#2B3343" }} id="image-upload-label">
                            {i18?.ACCOUNTSTITLE?.SELECT_ICONS || 'Select Icons'}
                        </InputLabel>
                        <input
                            type="file"
                            accept="image/png"
                            onChange={handleIconUpload}
                            style={{ margin: '10px 0px' }}
                        />
                        {iconPreview && (
                            <Box sx={{ marginTop: '10px' }}>
                                <img src={iconPreview} alt="Icon Preview" style={{ width: '100px', height: '100px' }} />
                            </Box>
                        )}
                    </Grid>
                    {/* <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px' }}>
                        <InputLabel sx={{ color: "#2B3343" }} id="image-upload-label">
                            {i18?.ACCOUNTSTITLE?.SELECT_IMAGES || 'Select Images'}
                        </InputLabel>
                        <input
                            type="file"
                            accept="image/*"
                            onChange={handleImageUpload}
                            style={{ margin: '10px 0px' }}
                        />
                        {categoryPreview && (
                            <Box sx={{ marginTop: '10px' }}>
                                <img src={categoryPreview} alt="Icon Preview" style={{ width: '100px', height: '100px' }} />
                            </Box>
                        )}
                    </Grid> */}
                </Grid>

                <Divider sx={{ backgroundColor: '#333', margin: '10px 0px 10px 0px' }} />

                <Grid container justifyContent="flex-end" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                    <Button
                        sx={{
                            padding: '10px 58px'
                        }}
                        disabled={!categoryName}
                        variant="contained"
                        onClick={addorUpdateCategory}
                    >
                        {cateId ? i18?.ACCOUNTSTITLE?.UPDATE || 'Update' : i18?.ACCOUNTSTITLE?.ADD || 'Add'}
                    </Button>
                </Grid>
            </Card>
        </>
    );
};

export default AdvCategoryForm;
